// ─── Master Obat — Detail Data (Dosis per Jenis Ternak) ──────────────────────
// SO-003: Detail farmakologi lengkap + tabel dosis per jenis ternak.
// Setiap dosis memiliki UUID internal.

// ─── Interfaces ───────────────────────────────────────────────────────────────

export interface DosisTernak {
  id: string;                    // UUID internal dosis
  jenisTernak: string;
  caraPemberian: string;
  dosis: string;
  frekuensi: string;
  lamaPemberian: string;
  maksDosis: string | null;
  catatan: string | null;
}

export interface ObatDetailFields {
  obatId: string;                // relasi ke ObatItem.id
  dosis: DosisTernak[];
  catatanPemberian?: string | null; // catatan umum tata cara pemberian (opsional)
}

